func (s restoreServers) verify(t *testing.T, wait time.Duration) (string, error) {
	t.Helper()
	admin := http.NewServeMux()
	// Liveness on admin must never satisfy the readiness gate on client TLS.
	admin.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
	admin.HandleFunc("GET /readyz", func(w http.ResponseWriter, _ *http.Request) {
		t.Error("readiness was requested on the admin listener")
		w.WriteHeader(http.StatusOK)
	})
	admin.HandleFunc("POST /admin/api-keys", func(w http.ResponseWriter, r *http.Request) {
		var body struct {
			Name           string   `json:"name"`
			Scopes         []string `json:"scopes"`
			OrganizationID string   `json:"organizationId"`
			ProjectID      string   `json:"projectId"`
			DatabaseID     string   `json:"databaseId"`
		}
		if err := json.UnmarshalRead(r.Body, &body); err != nil || body.Name != "restore-check" ||
			!slices.Equal(body.Scopes, []string{"documents:read"}) || body.OrganizationID != "00000000000000000000000001" ||
			body.ProjectID != "00000000000000000000000002" || body.DatabaseID != "00000000000000000000000003" {
			t.Errorf("API key request = %+v, %v", body, err)
		}
		w.WriteHeader(s.keyStatus)
		if s.keyStatus != http.StatusCreated {
			fmt.Fprint(w, `{"error":"invalid scopes"}`)
			return
		}
		fmt.Fprintf(w, `{"id":"key-1","secret":%q}`, s.keySecret)
	})
	adminServer := httptest.NewServer(admin)
	defer adminServer.Close()

	layout := Layout(t.TempDir())
	if err := os.Mkdir(layout.TLS(), 0o700); err != nil {
		t.Fatal(err)
	}
	caPEM, err := writeRestoreIdentity(layout, time.Now())
	if err != nil {
		t.Fatal(err)
	}
	pair, err := tls.LoadX509KeyPair(layout.Certificate(), layout.Key())
	if err != nil {
		t.Fatal(err)
	}
	clientServer := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/readyz" {
			if r.Header.Get("Authorization") != "" {
				t.Error("readiness should not need an API key")
			}
			w.WriteHeader(s.readyStatus)
			return
		}
		if r.URL.RequestURI() != restoreDocument || r.Header.Get("Authorization") != "Bearer s3cret" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		w.Header().Set("ETag", `"v7"`)
		w.WriteHeader(s.docStatus)
		fmt.Fprintf(w, `{"id":%q,"data":{"name":"restored"}}`, s.docID)
	}))
	clientServer.TLS = &tls.Config{Certificates: []tls.Certificate{pair}}
	clientServer.StartTLS()
	defer clientServer.Close()

	roots := x509.NewCertPool()
	roots.AppendCertsFromPEM(caPEM)
	transport := &http.Transport{TLSClientConfig: &tls.Config{RootCAs: roots}}
	defer transport.CloseIdleConnections()
	request := restoreCheckRequest{Document: restoreDocument, ReadyPath: "/readyz", organization: "00000000000000000000000001",
		project: "00000000000000000000000002", DatabaseID: "00000000000000000000000003", id: "00000000000000000000000005", wait: wait}
	return verifyRestore(t.Context(), &http.Client{Transport: transport, Timeout: 5 * time.Second},
		adminServer.URL, clientServer.URL, request)
}

func writeRestoreIdentity(layout Layout, now time.Time) ([]byte, error) {
	caPEM, caKey, err := NewCA("restore-check", now)
	if err != nil {
		return nil, err
	}
	caKeyPath := filepath.Join(layout.TLS(), "ca.key")
	if err := os.WriteFile(caKeyPath, caKey, 0o600); err != nil {
		return nil, err
	}
	defer os.Remove(caKeyPath)
	if err := os.WriteFile(layout.CA(), caPEM, 0o600); err != nil {
		return nil, err
	}
	ca, err := LoadCA(layout.CA(), caKeyPath)
	if err != nil {
		return nil, err
	}
	key, csr, err := NewMemberKey()
	if err != nil {
		return nil, err
	}
	certificate, err := ca.Issue(csr, Peer{Name: "restore-check", Address: netip.AddrPortFrom(netip.MustParseAddr("127.0.0.1"), 0)}, now)
	if err != nil {
		return nil, err
	}
	if err := os.WriteFile(layout.Key(), key, 0o600); err != nil {
		return nil, err
	}
	return caPEM, os.WriteFile(layout.Certificate(), certificate, 0o600)
}

func verifyRestore(ctx context.Context, client *http.Client, adminURL, clientURL string, request restoreCheckRequest) (string, error) {
	if err := waitRestoreReady(ctx, client, clientURL, request.ReadyPath, request.wait); err != nil {
		return "", err
	}
	body, err := json.Marshal(struct {
		Name           string   `json:"name"`
		Scopes         []string `json:"scopes"`
		OrganizationID string   `json:"organizationId"`
		ProjectID      string   `json:"projectId"`
		DatabaseID     string   `json:"databaseId"`
	}{"restore-check", []string{"documents:read"}, request.organization, request.project, request.DatabaseID})
	if err != nil {
		return "", err
	}
	response, data, err := restoreCall(ctx, client, http.MethodPost, adminURL+"/admin/api-keys", "", body)
	if err != nil {
		return "", fmt.Errorf("create restore-check API key: %w", err)
	}
	if response.StatusCode != http.StatusCreated {
		return "", fmt.Errorf("create restore-check API key: HTTP %d %q", response.StatusCode, snippet(data))
	}
	var key struct {
		Secret string `json:"secret"`
	}
	// The decode error is dropped: it could quote the secret.
	if json.Unmarshal(data, &key) != nil || key.Secret == "" {
		return "", errors.New("create restore-check API key: the response has no secret")
	}
	response, data, err = restoreCall(ctx, client, http.MethodGet, clientURL+request.Document, key.Secret, nil)
	if err != nil {
		return "", fmt.Errorf("read %s: %w", request.Document, err)
	}
	if response.StatusCode != http.StatusOK {
		return "", fmt.Errorf("read %s: HTTP %d %q", request.Document, response.StatusCode, snippet(data))
	}
	var document struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(data, &document); err != nil {
		return "", fmt.Errorf("read %s: %w", request.Document, err)
	}
	if document.ID != request.id {
		return "", fmt.Errorf("read %s: the document has id %q", request.Document, document.ID)
	}
	return response.Header.Get("ETag"), nil
}

func waitRestoreReady(ctx context.Context, client *http.Client, clientURL, readyPath string, wait time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, wait)
	defer cancel()
	for {
		response, data, err := restoreCall(ctx, client, http.MethodGet, clientURL+readyPath, "", nil)
		if err == nil && response.StatusCode == http.StatusOK {
			return nil
		}
		if err == nil {
			err = fmt.Errorf("HTTP %d %q", response.StatusCode, snippet(data))
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("terrabase did not answer %s with HTTP 200 within %s: %w (last: %v)", readyPath, wait, context.Cause(ctx), err)
		case <-time.After(250 * time.Millisecond):
		}
	}
}

// restoreCall sends one request, with a bearer secret when one is given,
// and returns the response with its body read up to restoreBodyLimit.
func restoreCall(ctx context.Context, client *http.Client, method, url, secret string, body []byte) (*http.Response, []byte, error) {
	request, err := http.NewRequestWithContext(ctx, method, url, bytes.NewReader(body))
	if err != nil {
		return nil, nil, err
	}
	if body != nil {
		request.Header.Set("Content-Type", "application/json")
	}
	if secret != "" {
		request.Header.Set("Authorization", "Bearer "+secret)
	}
	response, err := client.Do(request)
	if err != nil {
		return nil, nil, err
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, restoreBodyLimit))
	return response, data, err
}

func snippet(data []byte) string {
	return strings.TrimSpace(string(data[:min(len(data), 512)]))
}

func NewCA(cell string, now time.Time) (certificatePEM, keyPEM []byte, err error) {
	if !nameRE.MatchString(cell) {
		return nil, nil, errors.New("invalid cell name")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: "TerraBase member CA " + cell},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: now.Add(caValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		BasicConstraintsValid: true, IsCA: true, MaxPathLenZero: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), nil
}

// LoadCA reads a member CA written by NewCA. The key must be a regular
// file that only this process user owns and can read.
func LoadCA(certificateFile, keyFile string) (*CA, error) {
	certificatePEM, err := os.ReadFile(certificateFile)
	if err != nil {
		return nil, err
	}
	keyPEM, err := readOwnerOnly(keyFile)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA key: %w", err)
	}
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA: %w", err)
	}
	certificate := pair.Leaf
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if len(pair.Certificate) != 1 || !ok || !certificate.IsCA || certificate.KeyUsage&x509.KeyUsageCertSign == 0 {
		return nil, errors.New("terrabase member CA must be one CA certificate and its key")
	}
	return &CA{certificate: certificate, pem: certificatePEM, key: signer}, nil
}

// CertificatePEM is the CA certificate members trust.
func (ca *CA) CertificatePEM() []byte { return slices.Clone(ca.pem) }

// Issue signs a member's certificate request for its listed peer entry. The
// certificate names the member and its peer address, and serves both as the
// peer listener's server certificate and as the client certificate a member
// presents to other members.
func (ca *CA) Issue(csrDER []byte, peer Peer, now time.Time) ([]byte, error) {
	request, err := x509.ParseCertificateRequest(csrDER)
	if err != nil || request.CheckSignature() != nil {
		return nil, errors.New("invalid member certificate request")
	}
	if key, ok := request.PublicKey.(*ecdsa.PublicKey); !ok || key.Curve != elliptic.P256() {
		return nil, errors.New("member certificate request must use an ECDSA P-256 key")
	}
	notAfter := now.Add(memberValidity)
	if ca.certificate.NotAfter.Before(notAfter) {
		notAfter = ca.certificate.NotAfter
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: peer.Name},
		DNSNames: []string{peer.Name}, IPAddresses: []net.IP{peer.Address.Addr().AsSlice()},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: notAfter,
		KeyUsage:    x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, template, ca.certificate, request.PublicKey, ca.key)
	if err != nil {
		return nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), nil
}

// NewMemberKey creates a member's private key and the certificate request
// the host sends to the controller. The key never leaves the host.
func NewMemberKey() (keyPEM, csrDER []byte, err error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	csrDER, err = x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{}, key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), csrDER, nil
}

func readOwnerOnly(path string) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || !ok || owner.Uid != uint32(os.Getuid()) {
		return nil, errors.New("must be a regular file readable only by its owner, this process user")
	}
	return io.ReadAll(io.LimitReader(file, 64<<10))
}

func serial() *big.Int {
	n, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	if err != nil {
		panic(err)
	}
	return n.Add(n, big.NewInt(1))
}

func (l Layout) Data() string        { return filepath.Join(string(l), "data") }
func (l Layout) Bundle() string      { return filepath.Join(string(l), "bundle") }
func (l Layout) TLS() string         { return filepath.Join(string(l), "tls") }
func (l Layout) Key() string         { return filepath.Join(l.TLS(), "member.key") }
func (l Layout) Certificate() string { return filepath.Join(l.TLS(), "member.pem") }
func (l Layout) CA() string          { return filepath.Join(l.TLS(), "ca.pem") }

